                    cart[name].count--;
                    if (cart[name].count <= 0) {
                        delete cart[name];
                    }
                } else if (e.target.classList.contains('q9-inc')) {
                    cart[name].count++;
                }
                updateCartDisplay();
            }
        }
    });
});
